urlset:
{#- Pages and sections list all of their language editions; translation parity is enforced by
    scripts/validate-i18n.py, so those twins exist. Tag term pages are language-specific
    (a Czech tag is not a translation of an English one), so they carry no alternates. -#}
{%- set base = config.base_url ~ "/" -%}
{%- for entry in entries %}
  {%- set_global relative = entry.permalink | replace(from=base, to="") -%}
  {%- for code in config.extra.locales -%}
    {%- if code != config.default_language and relative is starting_with(pat=code ~ "/") -%}
      {%- set_global relative = relative[code | length + 1:] -%}
    {%- endif -%}
  {%- endfor %}
  {%- set is_term_page = relative is starting_with(pat="tags/") and relative != "tags/" %}
  {%- set_global matched = false -%}
  {%- for item in config.extra.localized_paths %}{% for code in config.extra.locales %}{% if relative == item[code] %}{% set_global matched = true %}{% set_global alias = item %}{% endif %}{% endfor %}{% endfor %}

    {{ entry.permalink | escape_xml }}
    {%- if entry.updated %}
    {{ entry.updated }}
    {%- endif %}
    {%- if not is_term_page %}
    {%- for code in config.extra.locales %}

    {%- endfor %}

    {%- endif %}

{%- endfor %}
